$ErrorActionPreference='Stop'
$repo=(Resolve-Path "$PSScriptRoot/../../..").Path
$data=[ordered]@{}
$names=@('hero_walk_run_grid','hero_back_idle','hero_command','portrait_hero_neutral','portrait_hero_determined','portrait_hero_surprised','portrait_hero_tired','officer_expressions')
foreach($name in $names){
 $data[$name]='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$PSScriptRoot/$name.png"))
 $old=if($name -like 'portrait*'){"$repo/Game/Assets/_Project/Story/Resources/StoryArt/$name.png"}elseif($name -eq 'officer_expressions'){"$repo/Game/Assets/_Project/Art/UI/Resources/HudArt/Tutorial/$name.png"}else{"$repo/Game/Assets/_Project/Art/Characters/Hero/$name.png"}
 $data["old_$name"]='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes($old))
}
foreach($name in @('hero_walk_run_grid_normal','hero_walk_run_grid_spec','hero_command_normal','hero_command_spec','hero_back_idle_normal','hero_back_idle_spec')){$data[$name]='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$PSScriptRoot/$name.png"))}
$data['night']='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$repo/Docs/References/beacon_game_20261022/05_pf_night_clean.png"))
$data['pick']='data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$repo/Docs/References/codex_k107_v1/comparison_front_night065_game_4x.png"))
$template=@'
<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>K-109 · 루멘 전체 그림</title>
<style>
:root{color-scheme:dark;font:16px/1.65 system-ui,sans-serif;background:#0b111a;color:#e9e2d2}*{box-sizing:border-box}body{margin:0}main{max-width:1260px;margin:auto;padding:40px 24px 80px}h1{font-size:38px;margin:8px 0}h2{margin:40px 0 12px;font-size:24px}h3{margin:0 0 8px}p{color:#b8c4cc;max-width:920px}.tag{color:#edc67d;letter-spacing:.1em}.tools{position:sticky;top:0;background:#101b2af5;border:1px solid #354257;padding:12px;z-index:10;display:flex;gap:12px;flex-wrap:wrap;align-items:center;border-radius:12px}button,select{background:#263449;color:#fff;border:1px solid #59708f;border-radius:7px;padding:8px 14px;font:inherit;cursor:pointer}input{accent-color:#edc67d}article{border:1px solid #344154;background:#121d2c;border-radius:12px;margin:18px 0;padding:20px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.stage{height:330px;position:relative;overflow:hidden;background:#152333;border:1px solid #40516b;border-radius:8px}.stage canvas{width:100%;height:100%;object-fit:contain;image-rendering:pixelated}.label{position:absolute;top:10px;left:12px;padding:3px 10px;background:#0a101cdd;color:#f3d496;border-radius:6px}.counter{color:#8ca2b5;font-size:13px}.portrait{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.portrait section{border:1px solid #344154;border-radius:8px;padding:12px;text-align:center}.portrait img{width:100%;max-width:170px;image-rendering:pixelated;background:repeating-conic-gradient(#1d2b3e 0% 25%,#152031 0% 50%) 0/20px 20px}.portrait .old{max-width:85px}.strip{width:100%;image-rendering:pixelated}.sheet{max-width:100%;image-rendering:pixelated}.maps{display:grid;grid-template-columns:1fr 1fr;gap:20px}.maps img{width:100%;max-height:560px;object-fit:contain;image-rendering:pixelated}details{margin:20px 0}summary{cursor:pointer;color:#edc67d}.notice{border-left:3px solid #dbb676;padding:8px 18px;background:#202b37}.status{color:#b9d7b6}table{border-collapse:collapse;width:100%;font-size:14px}td,th{border-bottom:1px solid #344154;padding:10px;text-align:left}@media(max-width:700px){main{padding:20px 12px}.pair,.maps{grid-template-columns:1fr}.portrait{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}.stage{height:300px}}
</style><main><div class="tag">K-109 · 루멘 파로스 · A안</div><h1>루멘 전체 그림</h1><p>선택한 비교판의 체형을 기준으로 만든 걷기·달리기·대기·지휘, 이야기 초상과 튜토리얼 표정입니다. 눈·입, 등대 문양, 허리 등불과 망원경을 확인할 수 있습니다.</p>
<p class="notice">실제 게임의 밤 성벽 사진 위에 새 그림과 현재 그림을 각각 합성했습니다. 인물 밝기만 0.65배이며, 조명·노멀·광택이 적용된 Unity 실행 화면은 아닙니다. 사진 속 기존 병력과 영웅도 그대로 남아 있습니다.</p>
<div class="tools"><button id="pause">일시정지</button><button id="step">한 칸 앞으로</button><label>배율 <select id="zoom"><option value="1">게임 장면 비율</option><option value="2">인물 2배 확대</option></select></label><label><input id="guides" type="checkbox" checked>발선·몸 중심</label><span id="status" class="status">그림 불러오는 중…</span></div><div id="motions"></div>
<h2>이야기 초상 · 전신 구도</h2><p>기존과 같은 256×384 투명 캔버스입니다. 위쪽은 루멘, 아래쪽은 현재 초상입니다.</p><div id="portraits" class="portrait"></div>
<h2>튜토리얼 표정</h2><p>기본 → 설명(손들기) → 긴급 → 만족. 기존과 같은 144×144 칸 4개입니다.</p><article><h3>루멘</h3><img class="strip" data-key="officer_expressions"><h3>현재 그림</h3><img class="strip" data-key="old_officer_expressions"></article>
<h2>노멀맵과 광택 마스크</h2><p>금장·등불 금속은 밝게, 천은 어둡게 분리했습니다. RGB 노멀맵의 바깥은 평평한 값이며 색 그림의 투명도로 잘립니다. 실제 빛 반응은 연결 후 확인해야 합니다.</p><div id="maps"></div>
<h2>규격과 선택 기준</h2><table><tr><th>항목</th><th>규격</th></tr><tr><td>걷기·달리기</td><td>4열×4행 / 후면 걷기·왼쪽 걷기·왼쪽 달리기·정면 걷기</td></tr><tr><td>후면 대기 / 지휘</td><td>1칸 / 3칸 (기본 → 손 올림 → 지휘)</td></tr><tr><td>원본 / 게임 셀</td><td>96×128 / 288×384 (최근접 3배)</td></tr><tr><td>발 피벗</td><td>원본 (48,120) / 게임 (144,360), 좌상단 기준</td></tr><tr><td>밝기·배경</td><td>인물 RGB ×0.65 / 실제 밤 사진 05_pf_night_clean.png</td></tr></table><details><summary>사용자가 선택한 K-107 비교판 보기 (두 번째 인물 A)</summary><img class="sheet" data-key="pick"></details><details><summary>전체 색 시트 보기</summary><img class="sheet" data-key="hero_walk_run_grid"><img class="sheet" data-key="hero_command"></details><p>게임 파일 교체·Unity 실행·커밋은 하지 않았습니다. 승인과 게임 연결은 별도입니다.</p></main>
<script>
const DATA=__DATA__;
const images={},motions=[['후면 걷기','hero_walk_run_grid',0,4,6],['왼쪽 걷기','hero_walk_run_grid',1,4,6],['왼쪽 달리기','hero_walk_run_grid',2,4,8],['정면 걷기','hero_walk_run_grid',3,4,6],['후면 대기','hero_back_idle',0,1,1],['지휘 · 마지막 칸 유지','hero_command',0,3,6]];
let paused=false,manual=0,start=performance.now();
for(const [title,key,row,count,fps] of motions){let a=document.createElement('article');a.innerHTML=`<h3>${title}</h3><div class="pair"><div class="stage"><span class="label">현재 영웅</span><canvas width="960" height="540"></canvas></div><div class="stage"><span class="label">루멘 A</span><canvas width="960" height="540"></canvas></div></div><div class="counter"></div>`;document.querySelector('#motions').append(a);}
for(const [key,title] of [['neutral','기본'],['determined','결의'],['surprised','놀람'],['tired','지침']]){let s=document.createElement('section');s.innerHTML=`<h3>${title}</h3><img data-key="portrait_hero_${key}"><br><img class="old" data-key="old_portrait_hero_${key}">`;document.querySelector('#portraits').append(s);}
for(const [key,title] of [['hero_walk_run_grid','걷기·달리기'],['hero_command','지휘'],['hero_back_idle','후면 대기']]){let a=document.createElement('article');a.innerHTML=`<h3>${title}</h3><div class="maps"><div>노멀<img data-key="${key}_normal"></div><div>광택<img data-key="${key}_spec"></div></div>`;document.querySelector('#maps').append(a);}
document.querySelectorAll('[data-key]').forEach(e=>{e.src=DATA[e.dataset.key];e.alt=e.dataset.key.startsWith('old_')?'현재 영웅 비교 그림':'루멘 제작 그림';});
function frame(m,t){if(m[1]==='hero_command'){let phase=(t/1000) % 2;return Math.min(2,Math.floor(phase*6));}return Math.floor(t*m[4]/1000)%m[3];}
function draw(){const elapsed=paused?manual:performance.now()-start;document.querySelectorAll('#motions article').forEach((a,i)=>{const m=motions[i],f=frame(m,elapsed),scale=Number(document.querySelector('#zoom').value);a.querySelectorAll('canvas').forEach((c,j)=>{const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,c.width,c.height);ctx.drawImage(images.night,0,0,960,540);const key=(j===0?'old_':'')+m[1],img=images[key],layer=document.createElement('canvas');layer.width=288;layer.height=384;const lc=layer.getContext('2d');lc.imageSmoothingEnabled=false;lc.drawImage(img,f*288,m[2]*384,288,384,0,0,288,384);const d=lc.getImageData(0,0,288,384);for(let p=0;p<d.data.length;p+=4){d.data[p]*=.65;d.data[p+1]*=.65;d.data[p+2]*=.65;}lc.putImageData(d,0,0);const px=500,py=450,w=112*scale,h=(384/288)*w;ctx.drawImage(layer,px-w/2,py-140*scale,w,h);if(document.querySelector('#guides').checked){ctx.strokeStyle='#d9bd78aa';ctx.lineWidth=1;ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(px-110*scale,py);ctx.lineTo(px+110*scale,py);ctx.moveTo(px,py-210*scale);ctx.lineTo(px,py+16);ctx.stroke();ctx.setLineDash([]);}});a.querySelector('.counter').textContent=`${f+1} / ${m[3]}칸 · ${m[4]}칸/초${m[3]===1?' · 정지 그림':''}`;});requestAnimationFrame(draw);}
document.querySelector('#pause').onclick=()=>{if(!paused){manual=performance.now()-start;paused=true;}else{start=performance.now()-manual;paused=false;}document.querySelector('#pause').textContent=paused?'재생':'일시정지';};document.querySelector('#step').onclick=()=>{if(!paused)manual=performance.now()-start;paused=true;manual+=1000/6;document.querySelector('#pause').textContent='재생';};
Promise.all(Object.entries(DATA).map(([key,src])=>new Promise((resolve,reject)=>{let i=new Image();i.onload=()=>{images[key]=i;resolve();};i.onerror=()=>reject(key);i.src=src;}))).then(()=>{document.querySelector('#status').textContent=`그림 ${Object.keys(images).length}개 불러옴`;draw();}).catch(key=>{document.querySelector('#status').textContent='그림 오류: '+key;});
</script></html>
'@
$html=$template.Replace('__DATA__',($data|ConvertTo-Json -Compress -Depth 3))
$dest="$repo/_HTML/6_그림_화면/codex_K-109_루멘전체그림_v1.html"
[IO.File]::WriteAllText($dest,$html,[Text.UTF8Encoding]::new($false))
Write-Output "검토 HTML 생성 완료: $dest"
